-- 表结构: base_class_info
DROP TABLE IF EXISTS `base_class_info`;
CREATE TABLE `base_class_info` (
  `org_id` bigint NOT NULL COMMENT '关联 sys_org.id',
  `head_teacher_id` bigint DEFAULT NULL COMMENT '班主任ID (sys_user.id)',
  `grade_year` int NOT NULL COMMENT '入学年份 (e.g., 2023)',
  `stage` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学段 (小学, 初中, 高中)',
  `graduation_status` tinyint DEFAULT '0' COMMENT '毕业状态 (0:在读, 1:已毕业)',
  `seating_chart` json DEFAULT NULL COMMENT '座位表数据结构 { groups: [{id, name, students: []}] }',
  `all_students` json DEFAULT NULL COMMENT '全班学生姓名列表',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '最后修改人ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  `deleted_by` bigint DEFAULT NULL COMMENT '删除人ID',
  `version` int DEFAULT '1' COMMENT '乐观锁版本号',
  `school_id` bigint DEFAULT NULL,
  `grade_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `student_count` int DEFAULT '0',
  PRIMARY KEY (`org_id`),
  KEY `idx_head_teacher` (`head_teacher_id`),
  KEY `idx_deleted_at` (`deleted_at`),
  KEY `idx_stage` (`stage`),
  KEY `idx_school_id` (`school_id`),
  CONSTRAINT `base_class_info_ibfk_1` FOREIGN KEY (`org_id`) REFERENCES `sys_org` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_class_info_school` FOREIGN KEY (`school_id`) REFERENCES `sys_org` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='班级扩展表';

