-- 表结构: base_class_teacher
DROP TABLE IF EXISTS `base_class_teacher`;
CREATE TABLE `base_class_teacher` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `class_id` bigint NOT NULL COMMENT '班级ID (sys_org.id)',
  `teacher_id` bigint NOT NULL COMMENT '教师ID (sys_user.id)',
  `subject` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任教科目 (chinese, math, english, physics, chemistry, biology, geography, politics, history, morality, it, pe, music)',
  `is_head_teacher` tinyint DEFAULT '0' COMMENT '是否班主任 (0:否, 1:是)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `status` int DEFAULT '1',
  `new_teacher_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_teacher_subject` (`class_id`,`subject`),
  KEY `idx_class_id` (`class_id`),
  KEY `idx_teacher_id` (`teacher_id`),
  CONSTRAINT `base_class_teacher_ibfk_1` FOREIGN KEY (`class_id`) REFERENCES `sys_org` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='班级教师任课表';

