-- 表结构: base_student
DROP TABLE IF EXISTS `base_student`;
CREATE TABLE `base_student` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `gender` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别 (M/F)',
  `student_no` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学号',
  `school_id` bigint NOT NULL COMMENT '所属学校ID',
  `class_id` bigint DEFAULT NULL COMMENT '所属班级ID',
  `grade_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '年级名称',
  `status` int DEFAULT '1' COMMENT '学籍状态 (1:在读, 2:休学, 3:退学, 4:毕业, 5:转出)',
  `dorm_building` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '宿舍楼',
  `dorm_floor` int DEFAULT NULL COMMENT '楼层',
  `dorm_room` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '宿舍号',
  `bed_no` int DEFAULT NULL COMMENT '床位号',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '最后修改人ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  `deleted_by` bigint DEFAULT NULL COMMENT '删除人ID',
  `version` int DEFAULT '1' COMMENT '乐观锁版本号',
  `score` decimal(6,2) DEFAULT '100.00' COMMENT '学生分数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_no` (`student_no`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_class_id` (`class_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=405 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学生档案表';

