-- 表结构: base_teacher
DROP TABLE IF EXISTS `base_teacher`;
CREATE TABLE `base_teacher` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '教师ID',
  `user_id` bigint DEFAULT NULL COMMENT '关联系统用户ID (sys_user.id)',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `gender` enum('M','F') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别 (M:男, F:女)',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `school_id` bigint DEFAULT NULL COMMENT '所属学校ID (sys_org.id)',
  `grades` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任教年级，多个年级用逗号分隔 (e.g., 初一,初二,高一)',
  `positions` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '岗位 (e.g., 班主任, 任课教师, 年级主任)',
  `subject` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任教学科 (语文,数学,英语,物理,化学,生物,政治,历史,地理,信息技术,体育,音乐,美术)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '最后修改人ID',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间',
  `deleted_by` bigint DEFAULT NULL COMMENT '删除人ID',
  `version` int DEFAULT '1' COMMENT '乐观锁版本号',
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_id` (`user_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_school_id` (`school_id`),
  KEY `idx_subject` (`subject`),
  KEY `idx_deleted_at` (`deleted_at`),
  CONSTRAINT `base_teacher_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE SET NULL,
  CONSTRAINT `base_teacher_ibfk_2` FOREIGN KEY (`school_id`) REFERENCES `sys_org` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_teacher_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='教师档案表';

