-- 表结构: biz_moral_record
DROP TABLE IF EXISTS `biz_moral_record`;
CREATE TABLE `biz_moral_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `student_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `student_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学生姓名快照',
  `class_id` bigint DEFAULT NULL COMMENT '当时所属班级 (快照，防调班后数据混乱)',
  `class_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '班级名称快照',
  `grade_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '年级名称快照',
  `rule_id` int NOT NULL COMMENT '关联指标ID',
  `major_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '大项分类快照 (对应cfg_moral_indicator.category)',
  `minor_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '小项分类快照 (对应cfg_moral_indicator.sub_category)',
  `rule_snapshot` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标名称快照 (防规则修改)',
  `score_change` decimal(4,1) NOT NULL COMMENT '变动分数 (+/-)',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '详细说明',
  `evidence_imgs` json DEFAULT NULL COMMENT '图片URL数组 (["http...", "http..."])',
  `evidence_audio` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '语音备注URL',
  `gps_lat` decimal(10,6) DEFAULT NULL COMMENT '纬度 (LBS校验)',
  `gps_lng` decimal(10,6) DEFAULT NULL COMMENT '经度 (LBS校验)',
  `location_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地点名称 (e.g., 教学楼305)',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'web' COMMENT '来源 (web, miniprogram, import)',
  `recorder_id` bigint DEFAULT NULL COMMENT '录入人ID',
  `recorder_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '录入人姓名快照',
  `record_time` datetime NOT NULL COMMENT '违纪/表彰发生时间',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '系统录入时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '最后修改人ID',
  PRIMARY KEY (`id`),
  KEY `idx_student_id` (`student_id`),
  KEY `idx_class_id` (`class_id`),
  KEY `idx_rule_id` (`rule_id`),
  KEY `idx_recorder_id` (`recorder_id`),
  KEY `idx_record_time` (`record_time`),
  KEY `idx_category` (`major_category`,`minor_category`),
  KEY `idx_student_time` (`student_id`,`record_time`),
  KEY `idx_class_time` (`class_id`,`record_time`),
  KEY `idx_source` (`source`),
  KEY `idx_major_category` (`major_category`),
  CONSTRAINT `biz_moral_record_ibfk_2` FOREIGN KEY (`rule_id`) REFERENCES `cfg_moral_indicator` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='德育检查记录表';

