-- 表结构: biz_teaching_record
DROP TABLE IF EXISTS `biz_teaching_record`;
CREATE TABLE `biz_teaching_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `teacher_id` bigint DEFAULT NULL,
  `check_item` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检查项目',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '详细内容',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型 (bonus/deduction/score)',
  `score` decimal(4,1) NOT NULL COMMENT '分数',
  `major_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '大项分类',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `indicator_id` int DEFAULT NULL COMMENT '关联教学指标ID',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `evidence_imgs` json DEFAULT NULL COMMENT '证据图片',
  `evidence_audio` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '语音备注URL',
  `gps_lat` decimal(10,6) DEFAULT NULL COMMENT '纬度',
  `gps_lng` decimal(10,6) DEFAULT NULL COMMENT '经度',
  `location_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '位置名称',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'web' COMMENT '来源',
  `recorder_id` bigint DEFAULT NULL COMMENT '录入人ID',
  `recorder_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '录入人姓名快照',
  `record_time` datetime NOT NULL COMMENT '记录时间',
  `class_id` bigint DEFAULT NULL COMMENT '班级ID(可选)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '最后修改人ID',
  PRIMARY KEY (`id`),
  KEY `idx_teacher_id` (`teacher_id`),
  KEY `idx_indicator_id` (`indicator_id`),
  KEY `idx_record_time` (`record_time`),
  KEY `idx_teacher_time` (`teacher_id`,`record_time`),
  KEY `idx_source` (`source`),
  KEY `idx_major_category` (`major_category`),
  CONSTRAINT `biz_teaching_record_ibfk_1` FOREIGN KEY (`teacher_id`) REFERENCES `base_teacher` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='教学记录表';

