-- 表结构: cfg_moral_indicator
DROP TABLE IF EXISTS `cfg_moral_indicator`;
CREATE TABLE `cfg_moral_indicator` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '指标ID',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '大项分类 (e.g., 德育常规, 卫生管理, 荣誉表彰)',
  `sub_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '小项分类 (e.g., 考勤纪律, 仪容仪表)',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标名称 (e.g., 上课迟到)',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型 (bonus:加分, deduction:扣分)',
  `default_score` decimal(4,1) NOT NULL COMMENT '默认分值',
  `org_id` bigint DEFAULT NULL COMMENT '所属组织ID (NULL表示全集团通用)',
  `is_enabled` tinyint DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_overall` int NOT NULL DEFAULT '0' COMMENT '1:整体检查项, 0:非整体检查项',
  PRIMARY KEY (`id`),
  KEY `idx_org_id` (`org_id`),
  KEY `idx_category` (`category`,`sub_category`),
  KEY `idx_enabled` (`is_enabled`),
  KEY `idx_is_overall` (`is_overall`),
  KEY `idx_category_sub` (`category`,`sub_category`),
  CONSTRAINT `cfg_moral_indicator_ibfk_1` FOREIGN KEY (`org_id`) REFERENCES `sys_org` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='评价指标库';

