-- 表结构: schedule_task
DROP TABLE IF EXISTS `schedule_task`;
CREATE TABLE `schedule_task` (
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `deleted_by` bigint DEFAULT NULL,
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_date` datetime NOT NULL,
  `start_time` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `end_time` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `creator_id` bigint NOT NULL,
  `school_id` bigint DEFAULT NULL,
  `assignee_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `assignee_id` bigint DEFAULT NULL,
  `assignee_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` text COLLATE utf8mb4_unicode_ci,
  `completed_at` datetime DEFAULT NULL,
  `completed_by` bigint DEFAULT NULL,
  `complete_remark` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `ix_schedule_task_status` (`status`),
  KEY `ix_schedule_task_task_type` (`task_type`),
  KEY `ix_schedule_task_school_id` (`school_id`),
  KEY `ix_schedule_task_creator_id` (`creator_id`),
  KEY `ix_schedule_task_id` (`id`),
  KEY `ix_schedule_task_task_date` (`task_date`),
  KEY `ix_schedule_task_deleted_at` (`deleted_at`),
  CONSTRAINT `schedule_task_ibfk_1` FOREIGN KEY (`creator_id`) REFERENCES `sys_user` (`id`),
  CONSTRAINT `schedule_task_ibfk_2` FOREIGN KEY (`school_id`) REFERENCES `sys_org` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

