-- 表结构: task_notification
DROP TABLE IF EXISTS `task_notification`;
CREATE TABLE `task_notification` (
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `id` bigint NOT NULL AUTO_INCREMENT,
  `task_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `notification_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci,
  `is_read` smallint NOT NULL,
  `read_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_task_notification_user_id` (`user_id`),
  KEY `ix_task_notification_id` (`id`),
  KEY `ix_task_notification_task_id` (`task_id`),
  CONSTRAINT `task_notification_ibfk_1` FOREIGN KEY (`task_id`) REFERENCES `schedule_task` (`id`),
  CONSTRAINT `task_notification_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

